/* Scoped learning experience for how-request-travels. */
document.addEventListener('keydown',e=>{
 const node=e.target.closest?.('.request-journey [data-scale-node]');
 if(!node||!['Enter',' '].includes(e.key))return;
 e.preventDefault();e.stopImmediatePropagation();
 scaleState.selectedNodeId=node.dataset.scaleNode;
 scaleState.isInspectorDrawerOpen=true;
 renderScaleApp();
 document.querySelector(`.request-journey [data-scale-node="${scaleState.selectedNodeId}"]`)?.focus();
},true);
const requestJourneySteps=[
 {name:'DNS & kết nối',subtitle:'Tìm địa chỉ, tạo kết nối',title:'Trước khi gửi request, trình duyệt cần biết đi đâu.',body:'Trình duyệt phân giải tên miền thành địa chỉ IP. Trong kịch bản HTTPS qua TCP của bài học này, nó tiếp tục thiết lập kết nối TCP và TLS với máy chủ ở biên trước khi trao đổi HTTP.',takeaway:'DNS tìm địa chỉ; TLS bảo vệ kết nối. Đây là hai nhiệm vụ khác nhau.',question:'DNS có mã hóa nội dung HTTP không?',answer:'Không. DNS phục vụ phân giải tên; TLS đảm nhiệm bảo vệ dữ liệu trên kết nối HTTPS. Kết quả DNS và kết nối có thể được dùng lại, nên không phải request nào cũng lặp toàn bộ các bước.',events:['Tìm IP từ tên miền','Thiết lập kết nối tới Edge'],terms:['DNS lookup','TCP','TLS'],source:'https://developer.mozilla.org/en-US/docs/Web/Performance/Guides/How_browsers_work'},
 {name:'CDN & WAF',subtitle:'Kiểm tra trước khi về origin',title:'Edge có thể trả lời mà không cần gọi ứng dụng.',body:'CDN kiểm tra khả năng phục vụ tài nguyên từ cache. Khi cần chuyển yêu cầu về origin, các lớp bảo vệ như WAF có thể kiểm tra theo bộ quy tắc đã cấu hình. Không phải mọi tài nguyên tĩnh đều được cache, hoặc mọi request động đều bắt buộc bỏ qua cache.',takeaway:'Cache hit giúp tránh gọi origin; cache miss cần đi tiếp theo chính sách cache và định tuyến.',question:'Có thể khẳng định mọi request /api đều không cache được không?',answer:'Không. Việc cache phụ thuộc nội dung, phương thức, header và chính sách. Cần đặc biệt thận trọng với nội dung cá nhân hóa hoặc cần kiểm soát quyền truy cập.',events:['Client gửi HTTPS tới Edge','Edge chuyển yêu cầu cần origin'],terms:['Cache hit','Cache miss','WAF'],source:'https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching'},
 {name:'Cân bằng tải',subtitle:'Chọn máy chủ xử lý',title:'Một điểm tiếp nhận, nhiều máy chủ cùng xử lý.',body:'Load balancer phân phối yêu cầu tới các app server phù hợp. Trong mô hình này, hệ thống dùng thông tin health check và chính sách định tuyến để chọn nơi xử lý. Hai nhánh biểu diễn các đích có thể chọn, không có nghĩa mỗi request được gửi cho cả hai server.',takeaway:'Health check cho biết đích có sẵn sàng nhận lưu lượng; thuật toán định tuyến quyết định cách phân phối.',question:'Thêm app server có luôn giúp hệ thống nhanh hơn không?',answer:'Không nhất thiết. Database, dịch vụ phía sau hoặc giới hạn tài nguyên khác vẫn có thể là nút thắt. Cần đo đúng tầng trước khi kết luận về hiệu quả mở rộng.',events:['Nhận request từ Edge','Chọn một app server sẵn sàng','Đích thay thế trong cụm'],terms:['Health check','Round robin','Stateless'],source:null},
 {name:'Cache & dữ liệu',subtitle:'Đọc dữ liệu, trả kết quả',title:'Ứng dụng chọn đường đọc dữ liệu phù hợp.',body:'Trong luồng đọc cache-aside minh họa, app kiểm tra cache trước. Nếu có dữ liệu phù hợp thì dùng kết quả đó; nếu không, app đọc database và có thể cập nhật cache. Hai nhánh trên sơ đồ là các đường xử lý theo điều kiện, không phải lúc nào cũng đọc cả hai.',takeaway:'Cache hit và cache miss là hai nhánh khác nhau. Luồng ghi và yêu cầu nhất quán cần quy tắc riêng.',question:'Cache hit có bảo đảm dữ liệu mới nhất không?',answer:'Không. Độ mới phụ thuộc TTL, invalidation và cách đồng bộ. Hãy xác định mức chấp nhận dữ liệu cũ của từng nghiệp vụ trước khi chọn chính sách.',events:['Kiểm tra dữ liệu trong Redis','Đọc database khi cache miss'],terms:['Cache-aside','TTL','Database'],source:null}
];
const journeyNodeInfo={client:['Trình duyệt','Khởi tạo yêu cầu và hiển thị kết quả từ hệ thống.','Xác định thao tác của người dùng, dữ liệu gửi đi và kết quả mong đợi.'],dns:['Phân giải tên miền','Giúp tìm địa chỉ IP tương ứng với tên miền trước khi thiết lập kết nối.','Phân biệt lỗi tìm địa chỉ với lỗi của ứng dụng; không gộp mọi lỗi vào “server lỗi”.'],cdn:['Máy chủ biên','Phục vụ nội dung cache phù hợp và chuyển tiếp yêu cầu cần origin.','Nội dung cá nhân hóa cần chính sách cache và kiểm soát truy cập phù hợp.'],lb:['Cân bằng tải','Chọn app server theo tình trạng sẵn sàng và quy tắc định tuyến.','Làm rõ hành vi khi một đích không sẵn sàng và khả năng retry an toàn.'],server:['Máy chủ ứng dụng','Thực thi logic nghiệp vụ và phối hợp với các tầng dữ liệu.','Lỗi nghiệp vụ, timeout và retry cần kết quả rõ ràng để tránh xử lý lặp.'],cache:['Bộ nhớ đệm','Giữ bản sao dữ liệu để giảm số lần truy cập nguồn chính.','Xác định mức chấp nhận dữ liệu cũ và trường hợp cần đọc nguồn đáng tin cậy.'],db:['Cơ sở dữ liệu','Lưu trữ và truy vấn dữ liệu phục vụ nghiệp vụ.','Xác định yêu cầu nhất quán, khả năng truy vết và cách xử lý khi truy vấn thất bại.']};
function RequestJourneyDiagram(diagram,selected){
 const names={client:'BROWSER',dns:'NAME RESOLUTION',cdn:'EDGE NETWORK',lb:'TRAFFIC ROUTING',server:'APPLICATION',cache:'IN-MEMORY',db:'PERSISTENCE'};
 return `<div class="journey-diagram-scroll" tabindex="0" aria-label="Sơ đồ tương tác; trên màn hình nhỏ có thể cuộn ngang"><svg class="journey-svg" viewBox="0 0 820 330" role="group" aria-label="Các thành phần trong bước hiện tại"><defs><pattern id="journey-dots" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="currentColor" opacity=".1"/></pattern><marker id="journey-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0 10 5 0 10" fill="none" stroke="currentColor" stroke-width="1.4"/></marker></defs><rect width="820" height="330" fill="url(#journey-dots)"/>${diagram.connections.map((c,i)=>{let a=diagram.nodes.find(n=>n.id===c.from),b=diagram.nodes.find(n=>n.id===c.to);if(!a||!b)return '';let sx=a.x+136,sy=a.y+42,ex=b.x,ey=b.y+42,mx=(sx+ex)/2;return `<g class="journey-wire"><path d="M${sx},${sy} C${mx},${sy} ${mx},${ey} ${ex-7},${ey}" fill="none" stroke="${c.color||'#818cf8'}" stroke-width="2" marker-end="url(#journey-arrow)"/><circle cx="${mx}" cy="${(sy+ey)/2}" r="11" fill="var(--gl-card)" stroke="var(--gl-border)"/><text x="${mx}" y="${(sy+ey)/2+4}" text-anchor="middle" font-size="10" fill="var(--gl-text-sub)">${i+1}</text></g>`}).join('')}${diagram.nodes.map(n=>`<g class="journey-node ${selected===n.id?'selected':''}" transform="translate(${n.x},${n.y})" role="button" tabindex="0" aria-label="Chi tiết ${escScale(n.label)}" aria-pressed="${selected===n.id}" data-scale-node="${escScale(n.id)}"><rect class="journey-node-bg" width="136" height="84" rx="12"/><rect x="12" y="13" width="29" height="25" rx="7" fill="var(--gl-primary-soft)"/><text x="26" y="30" text-anchor="middle" font-size="15" fill="var(--gl-primary)">${({client:'▣',dns:'◎',cdn:'☁',lb:'⑂',server:'⚙',cache:'ϟ',db:'▤'})[n.type]||'◇'}</text><text x="12" y="58" font-size="12" font-weight="600" fill="var(--gl-text)">${escScale(n.label.replace(' (PoP)','').replace(' (ALB)','').replace(' (WAF)',''))}</text><text x="12" y="73" font-size="7.5" letter-spacing="1" fill="var(--gl-text-sub)">${names[n.type]||'BUSINESS FLOW'}</text>${selected===n.id?'<circle cx="122" cy="17" r="4" fill="var(--gl-primary)"/>':''}</g>`).join('')}</svg></div>`;
}
function renderRequestJourney(stepNumber){
 const lesson=scaleLessonsDetail['how-request-travels'],step=Math.max(1,Math.min(lesson.steps.length,Number(stepNumber)||1)),data=lesson.steps[step-1],copy=requestJourneySteps[step-1];
 if(!scaleState.journeyReady){scaleState.isInspectorDrawerOpen=true;scaleState.journeyReady=true}
 const selected=data.diagram.nodes.find(n=>n.id===scaleState.selectedNodeId)||data.diagram.nodes.find(n=>n.id===data.diagram.activeNode)||data.diagram.nodes[0],info=journeyNodeInfo[selected.type]||journeyNodeInfo.server,done=scaleState.completedLessons.includes(lesson.slug);
 return `<div class="request-journey"><div class="journey-breadcrumb"><a href="#/books" data-nav="Sách BA">Sách BA</a><span>/</span><span>Phân tích nghiệp vụ</span><span>/</span><b>Luồng đặt hàng</b></div><div class="journey-heading"><div><div class="journey-kicker">THỰC HÀNH BUSINESS ANALYSIS</div><h1>Phân tích một luồng đặt hàng.</h1><p>Làm rõ đầu vào, quy tắc, tích hợp và kết quả cần nghiệm thu.</p></div><button class="journey-catalog-toggle" data-scale-action="toggle-lessons-sidebar" aria-expanded="${!!scaleState.isLessonSidebarOpen}">Học gì tiếp?</button></div><div class="journey-stepper" role="navigation" aria-label="Chọn bước trong hành trình">${requestJourneySteps.map((s,i)=>`<button data-scale-action="go-step" data-scale-step="${i+1}" class="${i+1===step?'active':i+1<step?'visited':''}" ${i+1===step?'aria-current="step"':''}><span class="journey-step-num">${String(i+1).padStart(2,'0')}</span><span><b>${s.name}</b><small>${s.subtitle}</small></span>${i+1===step?'<span class="journey-step-dot"></span>':''}</button>`).join('')}</div>${scaleState.isLessonSidebarOpen?`<div class="journey-catalog">${BARequestCatalogue()}</div>`:''}<div class="journey-grid ${scaleState.isInspectorDrawerOpen?'':'details-hidden'}"><div class="journey-stage"><section class="journey-canvas"><div class="journey-canvas-head"><div><span class="journey-section-kicker">LUỒNG NGHIỆP VỤ</span><h2>${copy.name}</h2></div><span class="journey-example-label">Kịch bản minh họa</span></div><div class="journey-browser"><span class="journey-browser-dots" aria-hidden="true">● ● ●</span><code>Tình huống: Khách đặt 2 sản phẩm</code><span>BA CASE</span></div>${RequestJourneyDiagram(data.diagram,selected.id)}<p class="journey-swipe-hint">Vuốt ngang sơ đồ để xem các thành phần còn lại.</p><div class="journey-flow-list">${data.diagram.connections.map((c,i)=>`<div><span>${i+1}</span><p>${copy.events[i]||'Chuyển yêu cầu'}</p><small>${escScale(c.label.replace(/^\d\. /,''))}</small></div>`).join('')}</div><div class="journey-canvas-note"><span>◎</span>Chọn một thành phần để xem BA cần làm rõ gì.<button data-scale-action="toggle-inspector" aria-expanded="${!!scaleState.isInspectorDrawerOpen}">${scaleState.isInspectorDrawerOpen?'Ẩn chi tiết':'Hiện chi tiết'}</button></div></section><section class="journey-explanation"><div class="journey-section-kicker">ĐIỀU GÌ ĐANG DIỄN RA?</div><h2>${copy.title}</h2><p>${copy.body}</p><div class="journey-takeaway"><span>✧</span><p><b>Điểm cần nhớ</b>${copy.takeaway}</p></div>${typeof renderBAArtifacts==='function'?renderBAArtifacts(copy):''}<div class="journey-tags">${copy.terms.map(t=>`<span>${t}</span>`).join('')}</div></section><section class="journey-controls" aria-label="Điều khiển bài học"><button data-scale-action="prev-step" ${step===1?'disabled':''}>Bước trước</button><span>${step} / ${lesson.steps.length} bước${done?' · Đã hoàn thành':''}</span><button class="journey-next" data-scale-action="${step===lesson.steps.length?'complete-lesson':'next-step'}">${step===lesson.steps.length?(done?'Đã hoàn thành':'Hoàn thành bài học'):'Bước tiếp theo'}</button></section></div><div class="journey-inspector"><section class="journey-inspect-card"><div class="journey-inspect-top"><span>THÀNH PHẦN ĐANG CHỌN</span><button data-scale-action="toggle-inspector" aria-label="Ẩn chi tiết thành phần">×</button></div><div class="journey-component-icon">${typeof uiIcon==='function'?uiIcon(selected.type==='client'?'grid':selected.type==='dns'?'target':selected.type==='db'?'data':'flow'):'◇'}</div><h2>${escScale(selected.label)}</h2><span class="journey-role">${info[0]}</span><div class="journey-inspect-section"><h3>Vai trò trong nghiệp vụ</h3><p>${info[1]}</p></div><div class="journey-ba-note"><span>BA CẦN LÀM RÕ</span><p>${info[2]}</p></div><button class="journey-reset" data-scale-action="reset-sim">Đặt lại bước hiện tại</button></section><section class="journey-check"><span class="journey-section-kicker">TỰ KIỂM TRA</span><h3>${copy.question}</h3><details><summary>Xem giải thích</summary><p>${copy.answer}</p></details></section></div></div><div class="journey-bottom"><span>Tình huống và quy tắc giả lập để luyện phân tích; cần xác nhận với stakeholder trước khi áp dụng.</span>${copy.source?`<a href="${copy.source}" target="_blank" rel="noopener noreferrer">Nguồn phương pháp</a>`:''}</div></div>`;
}
document.addEventListener('keydown',e=>{if(scaleState.activeSlug!=='how-request-travels'||scaleState.currentView!=='lesson')return;const node=e.target.closest('[data-scale-node]');if(node&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.stopImmediatePropagation();node.click()}} ,true);
